<?php defined('_JEXEC') or die;use Joomla\CMS\HTML\HTMLHelper;use Joomla\CMS\Router\Route; ?><div class="container-fluid"><h1>Drivers</h1><div class="row g-3 mb-4"><?php foreach($this->stats as $k=>$v): ?><div class="col-6 col-lg-3"><div class="card"><div class="card-body"><div class="text-muted"><?php echo ucfirst($k); ?></div><strong class="fs-3"><?php echo $v; ?></strong></div></div></div><?php endforeach; ?></div><div class="card mb-4"><div class="card-body"><h2 class="h4">Add driver</h2><form method="post" enctype="multipart/form-data" action="<?php echo Route::_('index.php?option=com_kaarbooking&task=drivers.save'); ?>" class="row g-3"><div class="col-md-3"><input class="form-control" name="display_name" required placeholder="Driver name"></div><div class="col-md-3"><select class="form-select" name="user_id"><option value="">Link Joomla/mobile account later</option><?php foreach($this->users as $u): ?><option value="<?php echo $u['id']; ?>"><?php echo htmlspecialchars($u['name'].' — '.$u['email'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-3"><select class="form-select" name="company_id"><option value="">Independent/operator</option><?php foreach($this->companies as $c): ?><option value="<?php echo $c['id']; ?>"><?php echo htmlspecialchars($c['name'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><input class="form-control" name="phone" placeholder="Masked/contact phone"></div><div class="col-md-2"><input class="form-control" name="licence_number" required minlength="5" placeholder="Driving licence number"></div><div class="col-md-3"><input class="form-control" type="file" name="profile_image" accept="image/jpeg,image/png,image/webp" required aria-label="Driver photograph"></div><div class="col-md-1"><button class="btn btn-primary">Add</button></div><?php echo HTMLHelper::_('form.token'); ?></form></div></div><form method="get" class="row g-2 mb-3"><input type="hidden" name="option" value="com_kaarbooking"><input type="hidden" name="view" value="drivers"><div class="col-md-3"><input class="form-control" name="filter_search" value="<?php echo htmlspecialchars($this->filters['search'],ENT_QUOTES,'UTF-8'); ?>" placeholder="Name or email"></div><div class="col-md-2"><select class="form-select" name="filter_company"><option value="">All companies</option><?php foreach($this->companies as $c): ?><option value="<?php echo $c['id']; ?>" <?php echo $this->filters['company']==$c['id']?'selected':''; ?>><?php echo htmlspecialchars($c['name'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><select class="form-select" name="filter_status"><option value="">All compliance</option><option>pending</option><option>verified</option><option>non_compliant</option></select></div><div class="col-md-2"><select class="form-select" name="filter_online"><option value="">All availability</option><option>online</option><option>offline</option></select></div><div class="col-md-2"><button class="btn btn-secondary">Filter</button> <a class="btn btn-link" href="<?php echo Route::_('index.php?option=com_kaarbooking&view=drivers'); ?>">Clear</a></div></form><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Photo</th><th>Name</th><th>Company/agency/union</th><th>Email</th><th>Driving licence</th><th>Status</th><th>Compliance</th><th>Availability</th></tr></thead><tbody><?php foreach($this->items as $i): ?><tr><td><?php if(!empty($i['image_path'])): ?><img src="<?php echo htmlspecialchars(\Joomla\CMS\Uri\Uri::root().$i['image_path'],ENT_QUOTES,'UTF-8'); ?>" alt="" width="64" height="48" style="object-fit:cover" loading="lazy"><?php endif; ?></td><td><?php echo htmlspecialchars($i['display_name'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($i['company_name']??'Independent/operator',ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($i['email']??'',ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($i['licence_number_masked']??'',ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($i['status'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($i['compliance_status'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($i['online_state'],ENT_QUOTES,'UTF-8'); ?></td></tr><?php endforeach; ?><?php if(!$this->items): ?><tr><td colspan="8">No drivers match the filters.</td></tr><?php endif; ?></tbody></table></div></div>




